insert into public.places (id,name,category,status,region_id,region_name,description,phone,address,website,opening_hours,alerts,source_name,source_url,verified_at)
values ('social-security-corporation','المؤسسة العامة للضمان الاجتماعي','government','published',NULL,NULL,'نظام تأمين اجتماعي عام وتكافلي يحمي الأفراد اجتماعيًا واقتصاديًا، ويحدد القانون منافعه ومصادر تمويلها، وتُموَّل المنافع من اشتراكات المؤمَّن عليهم وأصحاب العمل. يقدّم عبر موقعه خدمات للأفراد مثل الدفعة الواحدة والتعطل عن العمل وتقاعد الشيخوخة والتقاعد المبكر والأمومة وإصابات العمل والاستعلام عن الرقم الضماني وكشف الحساب والدفع الإلكتروني، وخدمات للمنشآت مثل التسجيل وتعديل الأجور والكتب الرسمية، وفيه بوابة وظائف.',NULL,NULL,'https://www.ssc.gov.jo',NULL,array['تحقق من الموقع الرسمي للتفاصيل الحالية'],'الموقع الرسمي للمؤسسة العامة للضمان الاجتماعي','https://www.ssc.gov.jo',now())
