insert into public.places (id,name,category,status,region_id,region_name,description,phone,address,website,opening_hours,alerts,source_name,source_url,verified_at)
values ('ministry-of-health','وزارة الصحة الأردنية','government','published',NULL,NULL,'الموقع الرسمي لوزارة الصحة. يقدّم خدمات إلكترونية لمزاولة المهن الصحية، وحجز مواعيد الفحص الطبي للوافدين والاستعلام عنها، ودليل الخدمات والنماذج، وخدمات مثل تطعيم الحمى الصفراء وبطاقات الإسعاف والطوارئ وشهادات صحية لعمال الحرف وتراخيص برك السباحة، إضافة إلى أدلة المستشفيات والصيدليات والمراكز الصحية والخريطة الصحية بتطبيقات للأندرويد والآيفون.','065004545 (الخط الساخن)',NULL,'https://www.moh.gov.jo',NULL,array['تحقق من الموقع الرسمي للتفاصيل الحالية'],'الموقع الرسمي لوزارة الصحة','https://www.moh.gov.jo',now())
