insert into public.places (id,name,category,status,region_id,region_name,description,phone,address,website,opening_hours,alerts,source_name,source_url,verified_at)
values ('ministry-of-labour','وزارة العمل الأردنية','government','published',NULL,NULL,'الموقع الرسمي لوزارة العمل، ويغطي تنظيم سوق العمل والتشريعات وبرامج التمويل والاتفاقيات. من خدماته منصة «حماية» لشكاوى العمل، ومنصة التشغيل الوطنية «سجّل»، وخدمات العمالة غير الأردنية، وبوابة تصاريح العمل، وبوابة التفتيش والسلامة والصحة المهنية، وطلبات ترخيص مكاتب التشغيل الخاصة، والإبلاغ عن عمل الأطفال، والدفع الإلكتروني.',NULL,NULL,'https://www.mol.gov.jo',NULL,array['تحقق من الموقع الرسمي للتفاصيل الحالية'],'الموقع الرسمي لوزارة العمل','https://www.mol.gov.jo',now())
