insert into public.places (id,name,category,status,region_id,region_name,description,phone,address,website,opening_hours,alerts,source_name,source_url,verified_at)
values ('greater-amman-municipality','أمانة عمّان الكبرى','government','published','amman','عمّان','بوابة الخدمات الإلكترونية لأمانة عمّان الكبرى. من خدماتها: الاستعلام عن المخالفات المرورية ودفعها والاعتراض عليها، وضريبة الأبنية والأراضي، وتسجيل عقود الإيجار، ورخص البناء والمهن، وتصاريح الهدم والحفر، وتصاريح الدفن، وتقديم الشكاوى، والدفع الإلكتروني ودليل الخدمات.','102 / 117180','رأس العين، شارع عمر مطر، عمّان','https://www.ammancity.gov.jo','الأحد إلى الخميس، 7:15 ص إلى 3:15 م',array['تحقق من الموقع الرسمي للتفاصيل الحالية'],'بوابة الخدمات الإلكترونية لأمانة عمّان الكبرى','https://www.ammancity.gov.jo',now())
