insert into public.places (id,name,category,status,region_id,region_name,description,phone,address,website,opening_hours,alerts,source_name,source_url,verified_at)
values ('just-university','جامعة العلوم والتكنولوجيا الأردنية','education','published','irbid','إربد','جامعة رسمية في إربد. يعرض موقعها الرؤية والرسالة والخطة الاستراتيجية والأنظمة، وثلاث عشرة كلية ومعهدًا منها الهندسة والطب والصيدلة والزراعة وتكنولوجيا المعلومات والدراسات العليا، إضافة إلى عمادات ومراكز بحث وخدمات الطلبة والقبول ومكتبة المئوية وخدمات الخريجين، وبرامج جديدة معلنة منها الأمن السيبراني والذكاء الاصطناعي والزراعة الرقمية.','+962 2 7201000','ص.ب. 3030، إربد، الرمز البريدي 22110','https://www.just.edu.jo',NULL,array['تحقق من الموقع الرسمي للتفاصيل الحالية'],'الموقع الرسمي لجامعة العلوم والتكنولوجيا الأردنية','https://www.just.edu.jo',now())
