insert into public.places (id,name,category,status,region_id,region_name,description,phone,address,website,opening_hours,alerts,source_name,source_url,verified_at)
values ('visit-jordan-tourism-board','هيئة تنشيط السياحة – زوروا الأردن','services','published',NULL,NULL,'الموقع الرسمي لهيئة تنشيط السياحة الأردنية (Visit Jordan) للترويج للسياحة في الأردن، ويتوفر بعدة لغات منها العربية والإنجليزية والألمانية والفرنسية والإسبانية والإيطالية واليابانية والروسية والصينية.','+962 6 567 8444',NULL,'https://www.visitjordan.com',NULL,array['تحقق من الموقع الرسمي للتفاصيل الحالية'],'الموقع الرسمي لهيئة تنشيط السياحة الأردنية','https://www.visitjordan.com',now())
